package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs in the create-owner pipeline after {@link BuildOwner} and before {@link SaveOwner}. Counts
 * the existing owners that already share this owner's firstName and lastName (compared
 * case-insensitively) at the moment before it is stored, and stamps that count onto the built owner
 * in place so later steps store and respond with it. As it runs before the owner is saved, the
 * count excludes the owner being created; the first owner of a name gets 0.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in the create-owner pipeline after {@link BuildOwner}. Resolves the effective registration
 * date — the value supplied in the request, or the server's current date when the request omitted
 * one — and adjusts it to a business day via {@link BusinessDays}: a Saturday or Sunday rolls
 * forward to the next Monday. The adjusted date is stored on the built owner in place, so later
 * steps derive from and respond with the resolved business-day value (formatted as ISO 'YYYY-MM-DD').
 */
public class DefaultOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate() != null
                ? owner.getRegistrationDate()
                : LocalDate.now();
        owner.setRegistrationDate(BusinessDays.adjust(effective));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

/**
 * Shared business-day adjustment for the create-owner pipeline. The effective registration date
